import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const shadowCard='a2-p08-r3c2',shadowChild='a2-p08-r1c1';
export const shadowCardScenarios=['shadow-card-ordinary','shadow-card-owner-ordinary','shadow-card-low-ordinary','shadow-card-dedicated','shadow-card-low-dedicated','shadow-card-shin-ordinary','shadow-card-shin-dedicated','shadow-card-high','shadow-card-equal','shadow-card-near','shadow-card-suppressed','shadow-card-silenced','shadow-card-stopped','shadow-card-prohibited','shadow-card-wrong-owner','shadow-card-decline','shadow-card-grant-decline','shadow-card-defense-fate','shadow-card-child-fate','shadow-card-child-low','shadow-card-child-chant','shadow-card-child-unchanted','shadow-card-child-follower','shadow-card-multi','shadow-card-shin-multi'] as const;
export type ShadowCardScenario=typeof shadowCardScenarios[number];
export function isShadowCardScenario(name:string):name is ShadowCardScenario{return (shadowCardScenarios as readonly string[]).includes(name);}
export function shadowCardMode(name:ShadowCardScenario){const dedicated=!['shadow-card-ordinary','shadow-card-owner-ordinary','shadow-card-low-ordinary','shadow-card-shin-ordinary','shadow-card-decline'].includes(name),owner=dedicated&&name!=='shadow-card-wrong-owner'||name==='shadow-card-owner-ordinary',shin=name.includes('-shin-'),multi=name.endsWith('-multi'),prohibited=name==='shadow-card-prohibited',incoming=multi?'a2-p10-r1c3':prohibited?'a2-p17-r1c2':name==='shadow-card-high'?'a2-p08-r2c2':name==='shadow-card-equal'?'a2-p08-r2c1':'a2-p24-r1c2',damage=multi?7:prohibited?4:name==='shadow-card-high'?8:name==='shadow-card-equal'?7:4,child=name==='shadow-card-near'?'a2-p08-r3c1':name==='shadow-card-child-chant'||name==='shadow-card-child-unchanted'?'a2-p13-r1c1':shadowChild;return {dedicated,owner,shin,multi,prohibited,incoming,damage,child};}
export function makeShadowCardPhysical(name:ShadowCardScenario,players:{id:string;name:string}[],options:{beforeAttack?:boolean;warrior?:number;attackerSpirit?:number;spirit?:number;childMagic?:number}={}){
 const m=shadowCardMode(name),prior=['shadow-card-suppressed','shadow-card-silenced','shadow-card-stopped'].includes(name),chantChild=name==='shadow-card-child-chant';let s=createGame(players,entropy(),{startingSeat:prior?3:chantChild?1:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.shin?'侍大将のシン':m.prohibited?'吟遊詩人のレスター':prior||m.multi?'聖騎士ランスロット':'黒妖精のアーネス',m.owner?'忍びのイダ':'黒騎士ガーウィン',m.shin?'竜皇子アスフェルト':m.multi?'黒妖精のアーネス':'侍大将のシン','魔導王ガイナス'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=(p.id===a?options.attackerSpirit??(m.multi?8:6):p.id===b?options.spirit??6:6)-gameStats(s,p.id).spirit;}
 s.players[b]!.permanent!.warrior_level!+=(options.warrior??(name.includes('-low')?4:5))-gameStats(s,b).warrior_level;if(options.childMagic!==undefined)s.players[b]!.permanent!.magic_level!+=options.childMagic-gameStats(s,b).magic_level;
 const keep=[takeCard(s,a,m.incoming),takeCard(s,b,shadowCard),takeCard(s,b,shadowChild),takeCard(s,b,'a2-p08-r3c1'),takeCard(s,b,'a2-p13-r1c1'),takeCard(s,b,'a2-p24-r1c3'),takeCard(s,c,'a2-p02-r1c3'),takeCard(s,d,'a2-p02-r2c3')];if(name==='shadow-card-near')keep.push(takeCard(s,a,'a2-p24-r2c1'));if(name==='shadow-card-child-follower')keep.push(takeCard(s,a,'a2-p22-r1c1'));if(prior)keep.push(takeCard(s,d,name==='shadow-card-suppressed'?'a2-p13-r1c2':name==='shadow-card-stopped'?'a2-p13-r2c1':'a2-p18-r1c1'));
 for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];s.events=[];
 function act(actorId:string,command:GameCommand,faces:number[]=Array(100).fill(1)){const input={actorId,command},e={...entropy(),dice:faces},r=transition(s,input,e);if(!r.ok)throw Error(`SHADOW_CARD_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('SHADOW_CARD_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('SHADOW_CARD_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<500;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},Array(100).fill(face));}throw Error('SHADOW_CARD_FIXTURE_LIMIT');}
 for(const id of [a,b,c,d]){if(id===a&&name==='shadow-card-child-follower')act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:'a2-p22-r1c1'});act(id,{type:'PASS_SETUP'});}
 function start(id:string){act(id,{type:'START_TURN'});settle();act(id,{type:'CHOOSE_DRAW',draw:false});}
 function end(id:string){if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});settle();}
 if(prior){start(d);act(d,{type:'ATTACK',cardInstanceId:name==='shadow-card-suppressed'?'a2-p13-r1c2':name==='shadow-card-stopped'?'a2-p13-r2c1':'a2-p18-r1c1',targetIds:[b],dedicated:false});settle(6);end(d);}
 if(chantChild){start(b);act(b,{type:'CHANT',cardInstanceId:'a2-p13-r1c1'});end(b);for(const id of [c,d]){start(id);act(id,{type:'PASS_ACTION'});end(id);}}
 start(a);if(m.multi){act(a,{type:'CHANT',cardInstanceId:m.incoming});end(a);for(const id of [b,c,d]){start(id);act(id,{type:'PASS_ACTION'});end(id);}start(a);}
 if(name==='shadow-card-near'){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r2c1',targetId:b});settle();}if(options.beforeAttack)return s;
 act(a,{type:'ATTACK',cardInstanceId:m.incoming,targetIds:m.multi&&m.shin?[b,c]:[b],dedicated:m.prohibited||m.multi&&m.shin});for(let n=0;n<500;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;act(w.participants[w.cursor]!,{type:'PASS'},Array(100).fill(m.multi?3:1));}throw Error('SHADOW_CARD_INCOMING');
}
